interface ProgressBarProps {
  value: number;
  max?: number;
  label: string;
  showValue?: boolean;
  size?: 'sm' | 'md' | 'lg';
}

const HEIGHT = { sm: 4, md: 8, lg: 16 };

export function ProgressBar({ value, max = 100, label, showValue = false, size = 'md' }: ProgressBarProps) {
  const pct = Math.min(100, Math.max(0, (value / max) * 100));
  const height = HEIGHT[size];

  return (
    <div>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 4 }}>
        <span id="progress-label">{label}</span>
        {showValue && <span aria-hidden="true">{Math.round(pct)}%</span>}
      </div>
      <div
        role="progressbar"
        aria-valuenow={value}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-labelledby="progress-label"
        aria-valuetext={`${label}: ${Math.round(pct)}%`}
        style={{
          width: '100%',
          height,
          background: '#e5e7eb',
          borderRadius: height / 2,
          overflow: 'hidden',
        }}
      >
        <div
          style={{
            width: `${pct}%`,
            height: '100%',
            background: '#0070f3',
            borderRadius: height / 2,
            transition: 'width 0.3s ease',
          }}
        />
      </div>
    </div>
  );
}

