interface Notice { id: string; message: string }
interface NoticeStore9 { items: Notice[]; push: (m: string) => void; clear: () => void }

export const useNoticeStore9 = create<NoticeStore9>()((set) => ({
  items: [],
  push: (message) => set((s) => ({ items: [...s.items, { id: String(Date.now()), message }] })),
  clear: () => set({ items: [] }),
}));

