import { useMutation, useQueryClient } from '@tanstack/react-query';

export function useCreateComment() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (body: { name: string }) => {
      const res = await fetch('/api/comments', {
        method: 'POST',
