import { useState, useId } from 'react';

interface CharCountTextareaProps {
  label: string;
  name: string;
  maxLength: number;
  warnAt?: number;
  rows?: number;
  required?: boolean;
}

export function CharCountTextarea({
  label,
  name,
  maxLength,
  warnAt = Math.floor(maxLength * 0.8),
  rows = 4,
  required,
}: CharCountTextareaProps) {
  const [value, setValue] = useState('');
  const id = useId();
  const countId = useId();
  const remaining = maxLength - value.length;
  const isWarning = remaining <= maxLength - warnAt;
  const isAtLimit = remaining === 0;

  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <textarea
        id={id}
        name={name}
        value={value}
        onChange={(e) => setValue(e.target.value.slice(0, maxLength))}
        rows={rows}
        required={required}
        aria-required={required}
        aria-describedby={countId}
        aria-invalid={isAtLimit}
        maxLength={maxLength}
      />
      <span
        id={countId}
        aria-live="polite"
        aria-atomic="true"
        style={{ color: isAtLimit ? 'red' : isWarning ? 'orange' : 'inherit' }}
      >
        {isAtLimit
          ? 'Character limit reached'
          : `${remaining} character${remaining !== 1 ? 's' : ''} remaining`}
      </span>
    </div>
  );
}

