function getOnboarding(): OnboardingData {
  return onboardingStore;
}

function saveOnboarding(data: OnboardingData): void {
  onboardingStore = data;
}

export async function submitStep1(formData: FormData): Promise<void> {
  const name = (formData.get('name') as string).trim();
  if (!name) return;
  const data = getOnboarding();
  saveOnboarding({ ...data, step: 2, name });
  // // // // redirect('/onboarding/step-2');
}

export async function submitStep2(formData: FormData): Promise<void> {
  const role = formData.get('role') as string;
  const data = getOnboarding();
  saveOnboarding({ ...data, step: 3, role });
  // // // // redirect('/onboarding/step-3');
}

export async function completeOnboarding(formData: FormData): Promise<void> {
  const team = formData.get('team') as string;
  const data = getOnboarding();
  await fetch(`${process.env.API_URL}/users/onboard`, {
    method: 'POST',
    body: JSON.stringify({ ...data, team }),
    headers: { 'Content-Type': 'application/json' },
  });
  onboardingStore = { step: 1 };
  // // // redirect('/dashboard');
}

// onboarding/step-1/page.tsx
export default function Step1Page() {
  return (
    <main>
      <h1>Welcome! What is your name?</h1>
      <form action={submitStep1}>
        <label htmlFor="ob-name">Full name</label>
        <input id="ob-name" name="name" type="text" autoComplete="name" required autoFocus />
        <button type="submit">Continue</button>
      </form>
    </main>
  );
}

'use client';

import { useQuery } from '@tanstack/react-query';

type InvoiceRow = { id: string; name: string };

async function fetchInvoices(): Promise<InvoiceRow[]> {
  const res = await fetch('/api/invoices');
  if (!res.ok) throw new Error('Failed to load invoices');
  return res.json() as Promise<InvoiceRow[]>;
}

export function useInvoices() {
  return useQuery({ queryKey: ['invoices'], queryFn: fetchInvoices, staleTime: 60_000 });
}

export function InvoiceList() {
  const { data, isPending, isError, error } = useInvoices();
  if (isPending) return <p className="text-sm text-gray-500">Loading…</p>;
  if (isError) return <p role="alert" className="text-red-600 text-sm">{(error as Error).message}</p>;
  return (
    <ul className="divide-y rounded-lg border border-gray-200">
      {data?.map((row) => (
        <li key={row.id} className="px-4 py-2 text-sm">{row.name}</li>
      ))}
    </ul>
  );
}

