import { useQueries } from '@tanstack/react-query';

export function Bundle1() {
  const results = useQueries({
    queries: [0, 1, 2].map((n) => ({
      queryKey: ['bundle-1', n],
      queryFn: () => fetch(`/api/bundle-1/${n}`).then((r) => r.json()),
    })),
