  if (results.some((r) => r.isPending)) return <p className="text-sm text-gray-500">Loading bundle…</p>;
  return (
    <div className="grid gap-2">
      {results.map((r, idx) => (
        <pre key={idx} className="rounded bg-gray-50 p-2 text-xs">{JSON.stringify(r.data)}</pre>
      ))}
    </div>
  );
}

