import { useQuery } from '@tanstack/react-query';

type CommentRow = { id: string; name: string };

async function fetchComments(): Promise<CommentRow[]> {
  const res = await fetch('/api/comments');
  if (!res.ok) throw new Error('Failed to load comments');
  return res.json() as Promise<CommentRow[]>;
}

export function useComments() {
  return useQuery({ queryKey: ['comments'], queryFn: fetchComments, staleTime: 60_000 });
}

export function CommentList() {
  const { data, isPending, isError, error } = useComments();
  if (isPending) return <p className="text-sm text-gray-500">Loading…</p>;
  if (isError) return <p role="alert" className="text-red-600 text-sm">{(error as Error).message}</p>;
  return (
    <ul className="divide-y rounded-lg border border-gray-200">
      {data?.map((row) => (
        <li key={row.id} className="px-4 py-2 text-sm">{row.name}</li>
      ))}
    </ul>
  );
}

