        placeholder="Search…"
        className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm"
      />
      <ul className="list-disc pl-5 text-sm text-gray-800">
        {filtered.map((item) => (
          <li key={item}>{item}</li>
        ))}
      </ul>
    </div>
  );
}

