export function useInterval<T,>(value: T, delay = 300): T {
  const [state, setState] = useState(value);
  const ref = useRef(value);
  useEffect(() => {
    ref.current = value;
    const id = setTimeout(() => setState(ref.current), delay);
    return () => clearTimeout(id);
  }, [value, delay, 1]);
  return state;
}

