import type { ReactNode } from 'react';

type Primitive = string | number | boolean | null | undefined;

interface ColumnDef<T> {
  accessor: keyof T;
  header: string;
  cell?: (value: T[keyof T], row: T) => ReactNode;
  sortable?: boolean;
}

interface DataGridProps<T extends Record<string, Primitive>> {
  caption: string;
  columns: ColumnDef<T>[];
  rows: T[];
  getRowKey: (row: T) => string;
  isLoading?: boolean;
  emptyMessage?: string;
}

export function DataGrid<T extends Record<string, Primitive>>({
  caption,
  columns,
  rows,
  getRowKey,
  isLoading = false,
  emptyMessage = 'No data available.',
}: DataGridProps<T>) {
  if (isLoading) {
    return (
      <div role="status" aria-busy="true" aria-label="Loading data">
        <span className="sr-only">Loading…</span>
      </div>
    );
  }

  if (rows.length === 0) {
    return <p role="status">{emptyMessage}</p>;
  }

  return (
    <div style={{ overflowX: 'auto' }}>
      <table>
        <caption>{caption}</caption>
        <thead>
          <tr>
            {columns.map((col) => (
              <th key={String(col.accessor)} scope="col">
                {col.header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map((row) => (
            <tr key={getRowKey(row)}>
              {columns.map((col) => (
                <td key={String(col.accessor)}>
                  {col.cell
                    ? col.cell(row[col.accessor], row)
                    : String(row[col.accessor] ?? '')}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

