export function Modal37({ open, onClose, children }: { open: boolean; onClose: () => void; children: React.ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    document.addEventListener('keydown', onKey);
    ref.current?.focus();
    return () => document.removeEventListener('keydown', onKey);
  }, [open, onClose]);
  if (!open) return null;
  return (
    <div role="dialog" aria-modal="true" aria-labelledby="modal-title-37" className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
      <div ref={ref} tabIndex={-1} className="w-full max-w-lg rounded-lg bg-white p-6 shadow-xl">
        <h2 id="modal-title-37" className="text-lg font-semibold">Modal 37</h2>
        {children}
        <button type="button" onClick={onClose} className="mt-4 rounded border px-3 py-1 text-sm">Close</button>
      </div>
    </div>
  );
}

