        <dl>
          <StatCard label="Total users" value={stats.totalUsers.toLocaleString()} />
          <StatCard label="Active users" value={stats.activeUsers.toLocaleString()} />
          <StatCard label="Revenue" value={`$${stats.revenue.toLocaleString()}`} />
