export function PageTransition{ 3 }({ children, keyId }: { children: React.ReactNode; keyId: string }) {
  return (
    <AnimatePresence mode="wait">
      <motion.div
        key={keyId}
        initial={ opacity: 0, x: 8 }
        animate={ opacity: 1, x: 0 }
        exit={ opacity: 0, x: -8 }
        className="min-h-screen"
      >
        {children}
      </motion.div>
    </AnimatePresence>
  );
}

