interface Column<T> {
  key: keyof T;
  label: string;
  sortable?: boolean;
  render?: (value: T[keyof T], row: T) => React.ReactNode;
}

interface AccessibleTableProps<T extends { id: string }> {
  caption: string;
  columns: Column<T>[];
  rows: T[];
  onSort?: (key: keyof T, direction: 'asc' | 'desc') => void;
  sortKey?: keyof T;
  sortDirection?: 'asc' | 'desc';
}

export function AccessibleTable<T extends { id: string }>({
  caption,
  columns,
  rows,
  onSort,
  sortKey,
  sortDirection = 'asc',
}: AccessibleTableProps<T>) {
  function handleSort(key: keyof T) {
    if (!onSort) return;
    const nextDir = sortKey === key && sortDirection === 'asc' ? 'desc' : 'asc';
    onSort(key, nextDir);
  }

  return (
    <table>
      <caption>{caption}</caption>
      <thead>
        <tr>
          {columns.map((col) => (
            <th
              key={String(col.key)}
              scope="col"
              aria-sort={
                col.sortable && sortKey === col.key
                  ? sortDirection === 'asc' ? 'ascending' : 'descending'
                  : col.sortable ? 'none' : undefined
              }
            >
              {col.sortable ? (
                <button
                  type="button"
                  onClick={() => handleSort(col.key)}
                  aria-label={`Sort by ${col.label}${sortKey === col.key ? `, currently ${sortDirection}ending` : ''}`}
                >
                  {col.label}
                  {sortKey === col.key && <span aria-hidden="true">{sortDirection === 'asc' ? ' ↑' : ' ↓'}</span>}
                </button>
              ) : col.label}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.map((row) => (
          <tr key={row.id}>
            {columns.map((col) => (
              <td key={String(col.key)}>
                {col.render ? col.render(row[col.key], row) : String(row[col.key])}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  );
}

