    <ul className="space-y-2">
      {optimistic.map((t) => (
        <li key={t.id} className="flex items-center gap-2">
          <input type="checkbox" checked={t.done} onChange={() => toggle(t.id)} />
          <span className={t.done ? 'line-through text-gray-400' : ''}>{t.label}</span>
        </li>
      ))}
    </ul>
  );
}

