import { useQuery } from '@tanstack/react-query';

type MessageRow = { id: string; name: string };

async function fetchMessages(): Promise<MessageRow[]> {
  const res = await fetch('/api/messages');
  if (!res.ok) throw new Error('Failed to load messages');
  return res.json() as Promise<MessageRow[]>;
}

export function useMessages() {
  return useQuery({ queryKey: ['messages'], queryFn: fetchMessages, staleTime: 60_000 });
}

export function MessageList() {
  const { data, isPending, isError, error } = useMessages();
  if (isPending) return <p className="text-sm text-gray-500">Loading…</p>;
  if (isError) return <p role="alert" className="text-red-600 text-sm">{(error as Error).message}</p>;
  return (
    <ul className="divide-y rounded-lg border border-gray-200">
      {data?.map((row) => (
        <li key={row.id} className="px-4 py-2 text-sm">{row.name}</li>
      ))}
    </ul>
  );
}

