interface ButtonProps {
  variant?: Variant;
  children: ReactNode;
  type?: 'button' | 'submit';
  disabled?: boolean;
  onClick?: () => void;
}

export function Button({
  variant = 'primary',
  children,
  type = 'button',
  disabled,
  onClick,
}: ButtonProps) {
